  text-transform: uppercase;
  opacity: 0.72;
}

.showcase-lead {
  margin: 0;
  max-width: 48rem;
  font-size: clamp(18px, 2vw, 23px);
  line-height: 1.6;
}

.showcase-actions,
.showcase-jump-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.showcase-actions a,
.showcase-jump-links a {
  display: inline-flex;
